var SHEET_ID = '1W6LJ8rPXvquuz9ZWn6KWaTI4Vnh2wqnUUuBVp48RfzM';
var SHEET_GID = 1351698221;

// Maps our internal field keys to the EXACT existing column header text
// in the Google Sheet (auto-generated by the linked Google Form).
var HEADER_MAP = {
  'nombre': 'Nombre y Apellidos(2) (Certificación):',
  'rut': 'RUT',
  'email': 'Email:',
  'telefono': 'Telefono:',
  'lineaNegocio': 'LÍNEA DE NEGOCIOS DE SU FORMACIÓN (Verifique correctamente)',
  'programa': 'PROGRAMA DISPONIBLES  (Marque Correctamente su formación)',
  'comprobante': 'Adjunta tu recibo de transferencia a continuación',
  'profesion': 'Profesión (debidamente acreditada por la Superintendencia de Salud)',
  'registro': 'Adjunte Registro Superintendencia de Salud VER AQUI (u certificado de titulo)',
  'razonSocial': 'Nombre o Razon Social ( Personal o sociedad):',
  'rutFacturacion': 'Rut o Run:',
  'giro': 'Giro:',
  'direccion': 'Dirección (Ser especifico, numero, calle, ciudad , región):',
  'aceptaPoliticas': 'Politicas términos comerciales | https://sanamaro.cl/politicas-comerciales/',
  'aceptaCertificacion': 'Certificación | https://sanamaro.cl/politicas-comerciales/',
  'aceptaVerificacion': 'Verificación'
};

var CHECKBOX_LABELS = {
  'aceptaPoliticas': 'He leído las políticas comerciales y estoy de acuerdo con ellas.',
  'aceptaCertificacion': 'He leído aspectos claves de la Certificación  y estoy de acuerdo con ellas.',
  'aceptaVerificacion': 'Confirmo que todos nuestros datos son 100% fidedignos, comprobables y respaldados por información real, lo que garantiza total transparencia en cada proceso.'
};

var TIMESTAMP_HEADER_CANDIDATES = ['Marca temporal', 'Timestamp'];

function doPost(e) {
  try {
    var data = JSON.parse(e.postData.contents);

    var sheet = getTargetSheet();
    var folder = getOrCreateFolder();

    var comprobanteUrl = data.comprobante ? saveFile(folder, data.comprobante, (data.nombre || 'Sin nombre') + ' - Comprobante') : '';
    var registroUrl = data.registro ? saveFile(folder, data.registro, (data.nombre || 'Sin nombre') + ' - Registro Profesional') : '';

    var lastCol = sheet.getLastColumn();
    var headers = sheet.getRange(1, 1, 1, lastCol).getValues()[0];
    var row = new Array(lastCol).fill('');

    var setByHeader = function (headerText, value) {
      var target = headerText.trim();
      for (var i = 0; i < headers.length; i++) {
        if (String(headers[i]).trim() === target) {
          row[i] = value;
          return true;
        }
      }
      return false;
    };

    TIMESTAMP_HEADER_CANDIDATES.forEach(function (h) { setByHeader(h, new Date()); });

    setByHeader(HEADER_MAP.nombre, data.nombre || '');
    setByHeader(HEADER_MAP.rut, data.rut || '');
    setByHeader(HEADER_MAP.email, data.email || '');
    setByHeader(HEADER_MAP.telefono, data.telefono || '');
    setByHeader(HEADER_MAP.lineaNegocio, data.lineaNegocio || '');
    setByHeader(HEADER_MAP.programa, data.programa || '');
    setByHeader(HEADER_MAP.comprobante, comprobanteUrl);
    setByHeader(HEADER_MAP.profesion, data.profesion || '');
    setByHeader(HEADER_MAP.registro, registroUrl);
    setByHeader(HEADER_MAP.razonSocial, data.razonSocial || '');
    setByHeader(HEADER_MAP.rutFacturacion, data.rutFacturacion || '');
    setByHeader(HEADER_MAP.giro, data.giro || '');
    setByHeader(HEADER_MAP.direccion, data.direccion || '');
    setByHeader(HEADER_MAP.aceptaPoliticas, data.aceptaPoliticas ? CHECKBOX_LABELS.aceptaPoliticas : '');
    setByHeader(HEADER_MAP.aceptaCertificacion, data.aceptaCertificacion ? CHECKBOX_LABELS.aceptaCertificacion : '');
    setByHeader(HEADER_MAP.aceptaVerificacion, data.aceptaVerificacion ? CHECKBOX_LABELS.aceptaVerificacion : '');

    sheet.appendRow(row);

    sendNotificationEmail(data, comprobanteUrl, registroUrl);

    return ContentService.createTextOutput(JSON.stringify({ ok: true }))
      .setMimeType(ContentService.MimeType.JSON);
  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({ ok: false, error: err.toString() }))
      .setMimeType(ContentService.MimeType.JSON);
  }
}

function getTargetSheet() {
  var ss = SpreadsheetApp.openById(SHEET_ID);
  var sheets = ss.getSheets();
  for (var i = 0; i < sheets.length; i++) {
    if (sheets[i].getSheetId() === SHEET_GID) return sheets[i];
  }
  return ss.getSheets()[0];
}

function getOrCreateFolder() {
  var props = PropertiesService.getScriptProperties();
  var id = props.getProperty('FOLDER_ID');
  if (id) {
    try { return DriveApp.getFolderById(id); } catch (e) {}
  }
  var folder = DriveApp.createFolder('Inscripciones - Archivos San Amaro');
  props.setProperty('FOLDER_ID', folder.getId());
  return folder;
}

function saveFile(folder, base64Data, fileName) {
  var parts = base64Data.split(',');
  var meta = parts[0];
  var match = meta.match(/data:(.*);base64/);
  var contentType = match ? match[1] : 'application/octet-stream';
  var bytes = Utilities.base64Decode(parts[1]);
  var blob = Utilities.newBlob(bytes, contentType, fileName);
  var file = folder.createFile(blob);
  file.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);
  return file.getUrl();
}

function sendNotificationEmail(data, comprobanteUrl, registroUrl) {
  var subject = 'Nueva inscripción: ' + (data.nombre || 'Sin nombre');
  var body =
    'Nueva inscripción recibida desde el sitio web:\n\n' +
    'DATOS DE CONTACTO\n' +
    'Nombre: ' + (data.nombre || '') + '\n' +
    'RUT: ' + (data.rut || '') + '\n' +
    'Email: ' + (data.email || '') + '\n' +
    'Teléfono: ' + (data.telefono || '') + '\n\n' +
    'PROGRAMA\n' +
    'Línea de negocio: ' + (data.lineaNegocio || '') + '\n' +
    'Programa: ' + (data.programa || '') + '\n' +
    'Profesión: ' + (data.profesion || '') + '\n\n' +
    'ARCHIVOS\n' +
    'Comprobante de transferencia: ' + (comprobanteUrl || '(no adjuntado)') + '\n' +
    'Registro profesional: ' + (registroUrl || '(no adjuntado)') + '\n\n' +
    'FACTURACIÓN\n' +
    'Razón Social: ' + (data.razonSocial || '') + '\n' +
    'RUT Facturación: ' + (data.rutFacturacion || '') + '\n' +
    'Giro: ' + (data.giro || '') + '\n' +
    'Dirección: ' + (data.direccion || '') + '\n';

  MailApp.sendEmail('info@sanamaro.cl', subject, body);
}
